## Setting Up Express

In your summarizer project folder, install Express:

```bash
npm install express
```

Create `server.js` in the same folder as your existing `summarize.js`:

```javascript
import express from 'express';
import Anthropic from '@anthropic-ai/sdk';

const app = express();
const client = new Anthropic();

// Parse form submissions
app.use(express.urlencoded({ extended: true }));

// Serve the HTML form
app.get('/', (req, res) => {
  res.send(`
    <!DOCTYPE html>
    <html>
    <head>
      <title>AI Summarizer</title>
      <style>
        body { font-family: system-ui; max-width: 800px; margin: 40px auto; padding: 0 20px; }
        textarea { width: 100%; height: 200px; margin: 10px 0; font-size: 16px; padding: 10px; }
        button { background: #6366f1; color: white; border: none; padding: 12px 24px; 
                 font-size: 16px; border-radius: 6px; cursor: pointer; }
        .result { margin-top: 20px; padding: 20px; background: #f8f9fa; border-radius: 8px; 
                  white-space: pre-wrap; line-height: 1.6; }
      </style>
    </head>
    <body>
      <h1>AI Text Summarizer</h1>
      <form method="POST" action="/summarize">
        <label>Paste your text below:</label>
        <textarea name="text" placeholder="Paste an article, document, or any text here..."></textarea>
        <button type="submit">Summarize</button>
      </form>
    </body>
    </html>
  `);
});

// Handle form submission
app.post('/summarize', async (req, res) => {
  const text = req.body.text;

  if (!text || text.trim().length < 50) {
    return res.send('<p>Please paste at least 50 characters of text. <a href="/">Go back</a></p>');
  }

  try {
    const message = await client.messages.create({
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 1024,
      messages: [{
        role: 'user',
        content: `Summarize this text concisely in 3-5 bullet points:\n\n${text}`
      }]
    });

    const summary = message.content[0].text;

    res.send(`
      <!DOCTYPE html>
      <html>
      <head><title>Summary</title>
        <style>
          body { font-family: system-ui; max-width: 800px; margin: 40px auto; padding: 0 20px; }
          .result { padding: 20px; background: #f8f9fa; border-radius: 8px; 
                    white-space: pre-wrap; line-height: 1.8; }
          a { color: #6366f1; }
        </style>
      </head>
      <body>
        <h1>Summary</h1>
        <div class="result">${summary}</div>
        <p><a href="/">Summarize another text</a></p>
      </body>
      </html>
    `);
  } catch (err) {
    res.send(`<p>Error: ${err.message}. <a href="/">Try again</a></p>`);
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

Run it: `node server.js` — then open `http://localhost:3000` in your browser.
